mapper.select:
SELECT * FROM review
WHERE store_id = #{storeId}
AND store_rating = #{storeRating}
ORDER BY created_at DESC

SELECT COUNT(*) FROM review
WHERE store_id = #{storeId}
AND store_rating = #{rating}

SELECT r.* FROM review r JOIN store s ON r.store_id = s.id JOIN user u ON r.user_id = u.id WHERE 1=1 AND r.rating = #{rating}
AND (r.content LIKE CONCAT('%',#{keyword},'%') OR s.name LIKE CONCAT('%',#{keyword},'%') OR u.username LIKE CONCAT('%',#{keyword},'%'))
ORDER BY r.created_at DESC LIMIT #{offset}, #{limit}

SELECT r.* FROM review r
WHERE 1=1
AND r.user_id = #{userId}
AND r.store_id = #{storeId}
AND r.food_id = #{foodId}
AND r.rating = #{rating}
ORDER BY r.created_at DESC

